    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 rate, uint256 duration) public payable {
        require(true);
        uint256 iZeroRate = c.interestFor(amount, 0, duration); if (__ESBMC_reverted()) return;
        uint256 iZeroDuration = c.interestFor(amount, rate, 0); if (__ESBMC_reverted()) return;
        assert(iZeroRate == 0 && iZeroDuration == 0);
    }

    receive() external payable {}
}

