pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 rate, uint256 duration) internal {
        vm.assume(true);
        uint256 iZeroRate;
        try c.interestFor(amount, 0, duration) returns (uint256 __r) { iZeroRate = __r; } catch { return; }
        uint256 iZeroDuration;
        try c.interestFor(amount, rate, 0) returns (uint256 __r) { iZeroDuration = __r; } catch { return; }
        assertTrue(iZeroRate == 0 && iZeroDuration == 0);
    }

    function testFuzz_run(uint256 amount, uint256 rate, uint256 duration) public {
        _run(amount, rate, duration);
    }

    receive() external payable {}
}
